-- Danh mục hành chính CŨ của SPX (trước sáp nhập) — trích từ template tạo đơn hàng loạt
-- (State_list / City_list / District_list). Phân cấp 3 tầng, tên IN HOA kiểu SPX:
--   Tỉnh/Thành (state) → Quận/Huyện (city) → Xã/Phường (ward).
-- Dùng để tách địa chỉ khách sang format SPX "địa chỉ cũ" khi xuất file tạo đơn.
-- Idempotent: CREATE IF NOT EXISTS + INSERT ... ON CONFLICT DO NOTHING.

CREATE TABLE IF NOT EXISTS spx_state_old (
  state text PRIMARY KEY               -- Tỉnh/Thành, vd 'TP. HỒ CHÍ MINH'
);

CREATE TABLE IF NOT EXISTS spx_city_old (
  state text NOT NULL,                 -- FK -> spx_state_old.state
  city  text NOT NULL,                 -- Quận/Huyện, vd 'QUẬN 5'
  PRIMARY KEY (state, city)
);
CREATE INDEX IF NOT EXISTS idx_spx_city_old_state ON spx_city_old (state);

CREATE TABLE IF NOT EXISTS spx_ward_old (
  city text NOT NULL,                  -- Quận/Huyện (khoá theo tên như District_list gốc)
  ward text NOT NULL,                  -- Xã/Phường, vd 'Phường 2'
  PRIMARY KEY (city, ward)
);
CREATE INDEX IF NOT EXISTS idx_spx_ward_old_city ON spx_ward_old (city);

